import{_ as t,o as a,c as o,a1 as e}from"./chunks/framework.CDRyr709.js";const i="/win10Sys.png",r="/win11Sys.png",p="/swabox-site.png",l="/swabox-st-DL.png",k=JSON.parse('{"title":"下载与安装","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start/setup.md","filePath":"quick-start/setup.md"}'),n={name:"quick-start/setup.md"};function c(d,s,h,u,b,g){return a(),o("div",null,[...s[0]||(s[0]=[e('<h1 id="下载与安装" tabindex="-1">下载与安装 <a class="header-anchor" href="#下载与安装" aria-label="Permalink to &quot;下载与安装&quot;">​</a></h1><hr><p>本章节将指引您下载并安装SWABox。</p><h1 id="检查系统配置" tabindex="-1">检查系统配置 <a class="header-anchor" href="#检查系统配置" aria-label="Permalink to &quot;检查系统配置&quot;">​</a></h1><hr><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>在您要在要运行 SWABox 的设备上安装 SWABox 前，都应该按照这部分的指引检查系统配置是否符合应用的需求。</p></div><p>要运行 SWABox，您的系统必须满足以下要求：</p><ul><li><strong>Windows</strong>: Windows 10 及以上版本的系统，x86_64 或 arm64 架构</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>该应用目前仅支持 Windows 操作系统。 欢迎各位贡献者为该应用测试并添加对其他操作系统的支持。</p></div><p>所以，我们需要先检查系统配置。根据您使用的操作系统，按照以下步骤查看系统配置信息：</p><h3 id="首先-我们要打开系统信息界面。" tabindex="-1">首先，我们要打开系统信息界面。 <a class="header-anchor" href="#首先-我们要打开系统信息界面。" aria-label="Permalink to &quot;首先，我们要打开系统信息界面。&quot;">​</a></h3><p>👉 <strong>按下 <code>Win</code> + <code>R</code> 打开【运行】窗口，输入以下命令，然后按下回车：</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">control</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Microsoft.System</span></span></code></pre></div><p>运行完命令后，系统应该会打开以下的一个界面，我们要重点关注划红圈的部分： <img src="'+i+'" alt="win10"></p><p><img src="'+r+'" alt="win11"></p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>这里的win10系统信息借用的是ClassIsland文档中的图片</p><p><a href="https://docs.classisland.tech/get-started/setup.html#%E6%A3%80%E6%9F%A5%E7%B3%BB%E7%BB%9F%E9%85%8D%E7%BD%AE" target="_blank" rel="noreferrer">原文档</a></p></div><p>👉 <strong>检查显示的系统要求是否符合 SWABox 运行所需的要求。</strong> 如果其中的“系统版本”所显示的系统版本大于或等于 Windows 10，那么您可以在此设备上运行 ClassIsland。</p><p>在“系统类型”中显示的是当前设备的架构和安装的系统类型。 <strong>“64 位操作系统”即代表您的操作系统是 x64 架构，“适用于 ARM 的 64 位操作系统”即代表您的操作系统是 arm64 架构。</strong></p><p>👉 <strong>记住此处显示的设备架构和系统类型。</strong></p><h1 id="下载-swabox" tabindex="-1">下载 SWABox <a class="header-anchor" href="#下载-swabox" aria-label="Permalink to &quot;下载 SWABox&quot;">​</a></h1><p>👉 <strong>在浏览器中打开<a href="https://swabox.cc.cd/" target="_blank" rel="noreferrer">https://swabox.cc.cd/</a> 下载 SWABox。</strong></p><p>此时您应该能看到如下页面： <img src="'+p+'" alt="swabox"></p><p>👉 <strong>点击导航栏中的“下载”按钮，自动下滑至如下区域:</strong><img src="'+l+'" alt="download-swabox"></p><p>👉 <strong>点击“下载”按钮，开始下载 SWABox。</strong></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>本网站提供的下载服务是通过github API实现的，大陆用户若下载速度过慢，请使用加速器或下载工具下载。</p></div><p>此时，您的浏览器应该会自动下载 SWABox。</p><h1 id="安装-swabox" tabindex="-1">安装 SWABox <a class="header-anchor" href="#安装-swabox" aria-label="Permalink to &quot;安装 SWABox&quot;">​</a></h1><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>本区域待开发</p></div>',28)])])}const x=t(n,[["render",c]]);export{k as __pageData,x as default};
